create function public.platform_admin_business_details(p_business uuid,p_from timestamptz default null,p_to timestamptz default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb;
begin
 if (select auth.uid()) is distinct from '706060a8-224f-43b9-ac78-ba86da094da5'::uuid then raise exception 'Acesso negado' using errcode='42501'; end if;
 if p_from is not null and p_to is not null and p_from>=p_to then raise exception 'Período inválido' using errcode='22023'; end if;
 if not exists(select 1 from public.businesses where id=p_business) then raise exception 'Negócio não encontrado' using errcode='P0002'; end if;
 select jsonb_build_object(
 'settings',(select jsonb_build_object('phone',s.social_links->>'phone','whatsapp',s.social_links->>'whatsapp','instagram',s.social_links->>'instagram','has_delivery',s.has_delivery,'has_takeaway',s.has_takeaway,'has_table_service',s.has_table_service,'pix_enabled',s.pix_enabled) from public.restaurant_settings s where s.business_id=p_business limit 1),
 'catalog',jsonb_build_object('active_products',(select count(*) from public.products where business_id=p_business and active),'categories',(select count(*) from public.categories where business_id=p_business),'active_staff',(select count(*) from public.staff where business_id=p_business and active),'active_coupons',(select count(*) from public.discount_coupons where business_id=p_business and active),'products_with_ingredients',(select count(distinct product_id) from public.product_ingredients where business_id=p_business)),
 'orders',(select jsonb_build_object('total',count(*),'pending',count(*) filter(where status='pending'),'accepted',count(*) filter(where status='accepted'),'delivered',count(*) filter(where status='delivered'),'delivery',count(*) filter(where order_type='delivery'),'takeaway',count(*) filter(where order_type='takeaway'),'table_service',count(*) filter(where order_type='table'),'delivered_total',coalesce(sum(total) filter(where status='delivered'),0),'average_delivered',coalesce(avg(total) filter(where status='delivered'),0),'paid',count(*) filter(where payment_status='paid'),'unpaid',count(*) filter(where payment_status='pending')) from public.orders where business_id=p_business and (p_from is null or created_at>=p_from) and (p_to is null or created_at<p_to)),
 'products',coalesce((select jsonb_agg(jsonb_build_object('name',x.name,'quantity',x.quantity) order by x.quantity desc,x.name) from (select item->>'name' name,sum((item->>'quantity')::numeric) quantity from public.orders o cross join lateral jsonb_array_elements(o.items) item where o.business_id=p_business and o.status='delivered' and (p_from is null or o.created_at>=p_from) and (p_to is null or o.created_at<p_to) and (item->>'quantity') ~ '^[0-9]+(\.[0-9]+)?$' group by item->>'name' order by quantity desc limit 10) x),'[]'::jsonb),
 'ingredients',coalesce((select jsonb_agg(jsonb_build_object('name',x.name,'quantity',x.quantity,'unit',x.unit) order by x.name) from (select min(u.name) name,case when public.canonical_ingredient_unit(u.unit) in ('g','kg') then 'g' when public.canonical_ingredient_unit(u.unit) in ('ml','l') then 'ml' else public.canonical_ingredient_unit(u.unit) end unit,sum(u.quantity * case when public.canonical_ingredient_unit(u.unit) in ('kg','l') then 1000 else 1 end) quantity from public.order_ingredient_usage u join public.orders o on o.id=u.order_id and o.business_id=u.business_id where u.business_id=p_business and o.status='delivered' and (p_from is null or o.delivered_at>=p_from) and (p_to is null or o.delivered_at<p_to) group by lower(trim(u.name)),case when public.canonical_ingredient_unit(u.unit) in ('g','kg') then 'g' when public.canonical_ingredient_unit(u.unit) in ('ml','l') then 'ml' else public.canonical_ingredient_unit(u.unit) end) x),'[]'::jsonb)
 ) into result;
 return result;
end $$;
revoke all on function public.platform_admin_business_details(uuid,timestamptz,timestamptz) from public, anon;
grant execute on function public.platform_admin_business_details(uuid,timestamptz,timestamptz) to authenticated;
